async function readRemoteResultJobId() {
    const showResult = await runGit([
        "show",
        `${REMOTE}/${BRANCH}:${RESULT_PATH}`
    ]);
    if (!showResult.ok) return "";
    try {
        return String(JSON.parse(showResult.stdout)?.jobId || "").trim();
    }
    catch {
        return "";
    }
}

